import{renderCustomModel,renderDiagram}from './visual.js?v=20261023-physicscomplete01';import{respFigure,respSVG,rt}from './resp-figures.js?v=20261023-physicscomplete01';import{buildResp}from './resp-meshes.js?v=20261023-physicscomplete01';
export function showResp(spec='aerobic:0',w={}){let[key,state]=spec.split(':'),kind=({'aerobic':'mitochondrion','anaerobic':'fermentation','exercise':'exercise','oxygen-debt':'recovery','metabolism':'metabolism'})[key]||key;let o={kind,state:state||'oxygen',...w},name=w.title||({'aerobic':'Respiration in living cells','anaerobic':'Compare the anaerobic products','exercise':'Read the exercise record','oxygen-debt':'Trace recovery','metabolism':'Build and break down molecules','mitochondrion':'Inside a mitochondrion','fermentation':'Compare anaerobic products','heat':'Compare living and control samples','yield':'Compare energy transfer','muscle':'Oxygen supply and muscle demand','recovery':'Trace recovery','recovery-data':'Read the recovery evidence','lipid':'Assemble a lipid'})[key]||'Inspect the process';let fig=o.concealed?respSVG(rt(280,180,'Predict, then reveal this comparison',23),name):respFigure({...o,title:name});if(['exercise','recovery-data','heat'].includes(kind)){renderDiagram(name,w.stateLabel||'Original evidence; use the stated units',fig,'RESPIRATION EVIDENCE');return;}renderCustomModel({name,formula:w.stateLabel||'Inspect; compare the labelled diagram',kicker:'SCHEMATIC BIOLOGY CUTAWAY',aria:name+'. Symbolic geometry; labelled diagram available.',atoms:[],bonds:[],radius:2.5,viewKey:'resp-'+kind,startPaused:true,note:'Symbolic scale and time · not a physiological forecast',diagram:fig,build:(g,T)=>buildResp(g,T,o)});}
